// Sample REQUEST transformer script.
// Modified from version originally generated by Claude.
// For learning purposes only.

(function(inputs) {
    /* inputs structure: {
        prompt_data: object,
        request_data: object
    } */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt;
    var model = promptData.model;

    // Output the inputs object to the system log for inspection
    // gs.info('LLM Transformer inputs: ' + JSON.stringify(inputs));

    // Anthropic Messages API body
    var body = {
        model: model,
        max_tokens: parseInt(promptData.max_tokens, 10),
        messages: [{
            "role": "user",
            "content": prompt
        }]
    };

    // Anthropic uses 0.0-1.0, not the 0-2 range some other providers use
    if (promptData.temperature !== undefined && promptData.temperature !== '') {
        body.temperature = parseFloat(promptData.temperature);
    }

    // Specify anthropic-version
    var headers = {
        "anthropic-version": "2023-06-01"
    };

    return {
        body: body,
        headers: headers
    };
})(inputs);

