// Sample RESPONSE transformer script.
// Modified from version originally generated by Claude.
// For learning purposes only.

(function(inputs) {
    /* inputs structure: {
        prompt_data: object,
        request_data: object,
        response_body: string,
        response_headers: string
    } */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var responseBody = JSON.parse(inputs.response_body);
    // gs.info("Claude response : " + inputs.response_body);
    var responseTexts = [];

    if (responseBody.content && Array.isArray(responseBody.content)) {
        // content is an array of blocks (text, tool_use, etc.) — concatenate the text blocks
        var text = '';
        for (var i = 0; i < responseBody.content.length; i++) {
            if (responseBody.content[i].type === "text") {
                text += responseBody.content[i].text;
            }
        }
        responseTexts.push(text);
    } else if (responseBody.error) {
        gs.error("Anthropic API error: " + JSON.stringify(responseBody.error));
        responseTexts.push('');
    }

    return responseTexts;
})(inputs);